contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address receiver) public { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(receiver == address(this));
        uint balC = address(c).balance;
        uint balThis = address(this).balance;
        bool reverted;
        c.sendTo(receiver, 0); if (__ESBMC_reverted()) return;
        reverted = false;
        assert(!reverted && address(c).balance == balC && address(this).balance == balThis);
    }
    receive() external payable {}
}

