// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MyContract c;

    function setUp() public {
        c = new MyContract();
    }

    function _run(address receiver) internal {
        vm.deal(address(c), VALUE_CAP);
        receiver = address(this);
        uint balC = address(c).balance;
        uint balThis = address(this).balance;
        bool reverted;
        try c.sendTo(receiver, 0) {} catch { return; }
        reverted = false;
        assertTrue(!reverted && address(c).balance == balC && address(this).balance == balThis);
    }

    function testFuzz_run(address receiver) public {
        _run(receiver);
    }

    receive() external payable {}
}
